(function runTransformScript(source, map, log, target /*undefined onStart*/ ) {

    // Add your code here
    var year1 = source.u_baujahr_beginn;
    var year2 = source.u_baujahr_ende;
    if (year && year.length === 4 && !isNaN(parseInt(year))) {
        gs.info(year1 + '-01-01' + ' , ' + year2 + '01-01');
        gs.info(typeof(year));
        target.production_year_from = year1 + '-01-01';
        target.production_year_to = year2 + '-01-01';

    }
    gs.info(year + '-01-01'); // leave empty if invalid
    gs.info(typeof(year));
    target.production_year_from = year1 + '-01-01';
    target.production_year_to = year2 + '-01-01'; // return the value to be put into the target field

})(source, map, log, target);
